 }

 fn caret(v: Version, given: usize) -> Vec<Comparator> {
-    // ^x.y.z only fixes the major version (see README).
-    let _ = given;
-    let upper = Version::new(v.major + 1, 0, 0);
+    let upper = if v.major > 0 || given == 1 {
+        Version::new(v.major + 1, 0, 0)
